import type { ComponentProps, ElementType, ReactNode } from "react";

import type { FooterColumn, FooterLink } from "@rhs-ui/marketing/footer-section";
import { RegionPicker } from "@rhs-ui/marketing/footer-region-selector/region-picker";
import { REGION_LABELS, type Region, type RegionLabels, type RegionOptions } from "@rhs-ui/marketing/footer-region-selector/types";
import { cn } from "@/lib/utils";

export type { Region, RegionChoice, RegionLabels, RegionOptions } from "@rhs-ui/marketing/footer-region-selector/types";

export interface FooterRegionSelectorProps extends Omit<ComponentProps<"footer">, "children"> {
  /** Your mark. */
  brand: ReactNode;
  /** One or two sentences under the mark. */
  tagline?: string;
  /** The link columns, above the region group. */
  columns: readonly FooterColumn[];
  /** The bottom row, left: "© 2026 Northwind Outdoor". */
  legal: ReactNode;
  /** The bottom row, right: privacy, terms, cookies. */
  legalLinks?: readonly FooterLink[];
  /** The region, when you control it. Pair with onRegionChange. */
  region?: Region;
  /** The region it starts with, when you do not control it. */
  defaultRegion?: Region;
  /** The countries, languages and currencies on offer. */
  options: RegionOptions;
  /** Called with all three codes every time one of the controls changes. Nothing navigates by itself: you switch the site, or store the choice. */
  onRegionChange?: (region: Region) => void;
  /** The language of the country names, in the list and in the summary. */
  locale?: string;
  /** Renders the internal links. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** The name of the navigation landmark, for a site that is not in English or a page with two footers. */
  navLabel?: string;
  /** Words for the fixed text, for a site that is not in English. */
  labels?: Partial<RegionLabels>;
}

const linkClass =
  "rounded-sm text-sm text-muted-foreground transition-colors duration-150 outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none";

/**
 * A footer for a shop or a product that sells in more than one market: link
 * columns above and, under them, a labelled Region group built on the house
 * selects, the searchable country list, the language and the currency. A
 * change calls onRegionChange with the full triple and nothing navigates by
 * itself, and a summary line ("Netherlands, English, EUR") says the current
 * choice in words. On a phone the group becomes one button that opens a dialog
 * with the same three fields, so the footer stays short. Every visible word,
 * the headings and the empty message of the country list included, is in
 * labels, and the country names follow locale. onRegionChange is a function,
 * so use the footer from a Client Component, or pass a Server Action.
 */
export function FooterRegionSelector({
  brand,
  tagline,
  columns,
  legal,
  legalLinks = [],
  region,
  defaultRegion,
  options,
  onRegionChange,
  locale = "en-US",
  linkAs: Link = "a",
  navLabel = "Footer",
  labels: custom,
  className,
  ...props
}: FooterRegionSelectorProps) {
  const words = { ...REGION_LABELS, ...custom };
  const renderLink = (link: FooterLink, extra?: string) =>
    link.external ? (
      <a href={link.href} target="_blank" rel="noopener noreferrer" className={cn(linkClass, extra)}>
        {link.label}
        <span className="sr-only"> ({words.newTab})</span>
      </a>
    ) : (
      <Link href={link.href} className={cn(linkClass, extra)}>
        {link.label}
      </Link>
    );

  return (
    <footer data-slot="footer-region-selector" className={cn("border-t border-border bg-background", className)} {...props}>
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <div className="grid gap-12 py-14 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,2fr)] lg:gap-16">
          <div className="grid content-start gap-4">
            <div>{brand}</div>
            {tagline ? <p className="max-w-xs text-sm leading-relaxed text-pretty text-muted-foreground">{tagline}</p> : null}
          </div>
          <nav aria-label={navLabel} className="grid grid-cols-2 gap-x-6 gap-y-10 sm:grid-cols-3 lg:grid-cols-[repeat(auto-fit,minmax(9rem,1fr))]">
            {columns.map((column) => (
              <div key={column.title} className="grid content-start gap-3">
                <h2 className="font-mono text-[0.6875rem] tracking-wide text-muted-foreground uppercase">{column.title}</h2>
                <ul className="grid gap-2.5">
                  {column.links.map((link) => (
                    <li key={`${link.label}-${link.href}`}>{renderLink(link)}</li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </div>

        <RegionPicker className="border-t border-border py-8" region={region} defaultRegion={defaultRegion} options={options} onRegionChange={onRegionChange} locale={locale} labels={words} />

        <div className="flex flex-col gap-3 border-t border-border py-6 text-xs text-muted-foreground sm:flex-row sm:items-center sm:justify-between">
          <div>{legal}</div>
          {legalLinks.length ? (
            <ul className="flex flex-wrap gap-x-5 gap-y-2">
              {legalLinks.map((link) => (
                <li key={`${link.label}-${link.href}`}>{renderLink(link, "text-xs")}</li>
              ))}
            </ul>
          ) : null}
        </div>
      </div>
    </footer>
  );
}

import type { ComboboxOption } from "@rhs-ui/primitives/combobox";

/** ISO 3166-1 alpha-2 codes, for a footer that offers every country. The names come from the browser, in the language of the page (Intl.DisplayNames). */
export const COUNTRY_CODES =
  "AD AE AF AG AI AL AM AO AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GT GU GW GY HK HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG US UY UZ VA VC VE VG VI VN VU WF WS XK YE YT ZA ZM ZW".split(" ");

/** The flag of a country, as the two regional-indicator letters that spell its code. */
const flag = (code: string) => String.fromCodePoint(...[...code.toUpperCase()].map((char) => 0x1f1e6 + char.charCodeAt(0) - 65));

/** Names countries in a language, with one Intl.DisplayNames behind it. A code the browser does not know comes back as the code, so a typo shows instead of breaking the footer. */
function countryNamer(locale: string): (code: string) => string {
  let names: Intl.DisplayNames | null = null;
  try {
    names = new Intl.DisplayNames([locale], { type: "region" });
  } catch {
    names = null;
  }
  return (code) => {
    try {
      return names?.of(code.toUpperCase()) ?? code;
    } catch {
      return code;
    }
  };
}

/** The name of a country in a language: "Netherlands", "Nederland". */
export function countryName(code: string, locale: string): string {
  return countryNamer(locale)(code);
}

export interface CountryOptionsInput {
  /** The countries on offer, as ISO codes. Left out, every country. */
  only?: readonly string[];
  /** Countries listed first, under their own heading. */
  suggested?: readonly string[];
  /** The language of the names. */
  locale: string;
  /** The heading over the suggested countries. */
  suggestedLabel: string;
  /** The heading over the rest, shown when there are suggested countries. */
  allLabel: string;
}

/**
 * The options of the country list: the suggested countries first, then the rest by name in the language of the page, each with its flag and
 * with its code as a search keyword. The two headings are passed in, so they can be in that language too.
 */
export function countryOptions({ only, suggested = [], locale, suggestedLabel, allLabel }: CountryOptionsInput): ComboboxOption[] {
  const codes = only ?? COUNTRY_CODES;
  const nameOf = countryNamer(locale);
  const make = (code: string, group?: string): ComboboxOption => ({ value: code, label: `${flag(code)}  ${nameOf(code)}`, keywords: [code, nameOf(code)], group });
  const top = suggested.filter((code) => codes.includes(code)).map((code) => make(code, suggestedLabel));
  const rest = codes
    .filter((code) => !suggested.includes(code))
    .sort((a, b) => nameOf(a).localeCompare(nameOf(b), locale))
    .map((code) => make(code, top.length ? allLabel : undefined));
  return [...top, ...rest];
}

"use client";

import { useId, useMemo, useState } from "react";

import { IconChevronDown, IconGlobe } from "@rhs-ui/icons";
import { countryName, countryOptions } from "@rhs-ui/marketing/footer-region-selector/countries";
import type { Region, RegionLabels, RegionOptions } from "@rhs-ui/marketing/footer-region-selector/types";
import { Button } from "@rhs-ui/primitives/button";
import { Combobox } from "@rhs-ui/primitives/combobox";
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@rhs-ui/primitives/dialog";
import { Label } from "@rhs-ui/primitives/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@rhs-ui/primitives/select";
import { cn } from "@/lib/utils";

export interface RegionPickerProps {
  /** The region, when you control it. Pair with onRegionChange. */
  region?: Region;
  /** The region it starts with, when you do not control it. */
  defaultRegion?: Region;
  /** The countries, languages and currencies on offer. */
  options: RegionOptions;
  /** Called with all three codes every time one of the controls changes. Nothing navigates by itself. */
  onRegionChange?: (region: Region) => void;
  /** The language of the country names, in the list and in the summary. */
  locale: string;
  /** The fixed words. */
  labels: RegionLabels;
  /** Classes for the group. */
  className?: string;
}

interface RegionFieldsProps {
  idBase: string;
  region: Region;
  options: RegionOptions;
  locale: string;
  labels: RegionLabels;
  onChange: (patch: Partial<Region>) => void;
  className?: string;
}

const caption = "text-xs font-normal text-muted-foreground";

interface CountryFieldProps {
  id: string;
  value: string;
  onValueChange: (country: string) => void;
  options: RegionOptions;
  locale: string;
  labels: RegionLabels;
}

/**
 * The searchable country list on the house combobox. CountrySelect would do the same, but it says "Suggested", "All countries", "Search
 * countries" and "No country found" in English whatever the page speaks, so the list is built here with the words of the footer's labels.
 */
function CountryField({ id, value, onValueChange, options, locale, labels }: CountryFieldProps) {
  const list = useMemo(
    () => countryOptions({ only: options.countries, suggested: options.suggestedCountries, locale, suggestedLabel: labels.suggested, allLabel: labels.allCountries }),
    [options.countries, options.suggestedCountries, locale, labels.suggested, labels.allCountries],
  );
  return (
    <Combobox
      id={id}
      options={list}
      value={value}
      onValueChange={onValueChange}
      label={labels.country}
      placeholder={labels.chooseCountry}
      searchPlaceholder={labels.searchCountries}
      emptyText={labels.noCountry}
    />
  );
}

/** The three labelled fields, shared by the bar and the dialog, so neither can drift from the other. */
function RegionFields({ idBase, region, options, locale, labels, onChange, className }: RegionFieldsProps) {
  return (
    <div className={cn("grid gap-3", className)}>
      <div className="grid gap-1.5">
        <Label htmlFor={`${idBase}-country`} className={caption}>
          {labels.country}
        </Label>
        <CountryField id={`${idBase}-country`} value={region.country} onValueChange={(country) => onChange({ country })} options={options} locale={locale} labels={labels} />
      </div>
      <div className="grid gap-1.5">
        <Label htmlFor={`${idBase}-language`} className={caption}>
          {labels.language}
        </Label>
        <Select value={region.language} onValueChange={(language) => onChange({ language })}>
          <SelectTrigger id={`${idBase}-language`}>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {options.languages.map((choice) => (
              <SelectItem key={choice.value} value={choice.value} description={choice.hint}>
                {choice.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="grid gap-1.5">
        <Label htmlFor={`${idBase}-currency`} className={caption}>
          {labels.currency}
        </Label>
        <Select value={region.currency} onValueChange={(currency) => onChange({ currency })}>
          <SelectTrigger id={`${idBase}-currency`}>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {options.currencies.map((choice) => (
              <SelectItem key={choice.value} value={choice.value} description={choice.hint}>
                {choice.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
    </div>
  );
}

/**
 * The Region group of the footer: from md up a labelled group with the three
 * fields and a summary line that says the current choice in words; below md one
 * button that shows the same summary and opens a dialog with the same three
 * fields, which keeps the footer short. Changing a control calls
 * onRegionChange with the full triple and nothing else happens.
 */
export function RegionPicker({ region, defaultRegion, options, onRegionChange, locale, labels, className }: RegionPickerProps) {
  const id = useId();
  const [own, setOwn] = useState<Region>(
    defaultRegion ?? { country: options.countries?.[0] ?? "US", language: options.languages[0]?.value ?? "en", currency: options.currencies[0]?.value ?? "USD" },
  );
  const current = region ?? own;
  const change = (patch: Partial<Region>) => {
    const next = { ...current, ...patch };
    if (region === undefined) setOwn(next);
    onRegionChange?.(next);
  };
  const summary = [
    countryName(current.country, locale),
    options.languages.find((choice) => choice.value === current.language)?.label ?? current.language,
    options.currencies.find((choice) => choice.value === current.currency)?.label ?? current.currency,
  ].join(", ");

  return (
    <div data-slot="footer-region-picker" className={className}>
      <div role="group" aria-labelledby={`${id}-heading`} className="hidden gap-5 md:grid lg:grid-cols-[minmax(0,1fr)_auto] lg:items-end lg:gap-8">
        <div className="grid content-start gap-2">
          <h2 id={`${id}-heading`} className="flex items-center gap-2 font-mono text-[0.6875rem] tracking-wide text-muted-foreground uppercase">
            <IconGlobe aria-hidden="true" className="size-3.5" />
            {labels.region}
          </h2>
          <p aria-live="polite" className="text-sm font-medium">
            {summary}
          </p>
        </div>
        <RegionFields idBase={`${id}-bar`} region={current} options={options} locale={locale} labels={labels} onChange={change} className="md:grid-cols-3 lg:grid-cols-[repeat(3,12rem)]" />
      </div>

      <Dialog>
        <DialogTrigger asChild>
          <Button variant="outline" className="h-auto min-h-11 w-full justify-between px-3.5 py-2 font-normal md:hidden">
            {/* The summary wraps instead of being cut: the currency is the last of its three values, and the one a narrow screen would lose. */}
            <span className="flex min-w-0 items-center gap-2.5">
              <IconGlobe aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
              <span className="sr-only">{labels.region}: </span>
              <span className="text-left whitespace-normal">{summary}</span>
            </span>
            <IconChevronDown aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
          </Button>
        </DialogTrigger>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{labels.region}</DialogTitle>
            <DialogDescription>{labels.description}</DialogDescription>
          </DialogHeader>
          <RegionFields idBase={`${id}-dialog`} region={current} options={options} locale={locale} labels={labels} onChange={change} />
          <DialogFooter>
            <DialogClose asChild>
              <Button>{labels.done}</Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/** What the visitor chose: three codes, which is all your callback needs to switch the site, the copy and the prices. */
export interface Region {
  /** An ISO 3166-1 alpha-2 code: "NL". */
  country: string;
  /** Your own code for the language: "en", "nl", "pt-BR". */
  language: string;
  /** An ISO 4217 code: "EUR". */
  currency: string;
}

/** One option of the language or the currency list. */
export interface RegionChoice {
  /** What goes in the Region: "de", "EUR". */
  value: string;
  /** What the visitor reads. A language is named in itself ("Deutsch"), a currency by its code ("EUR"). */
  label: string;
  /** A second line in the list: "German", "Euro". The summary and the closed field show the label only. */
  hint?: string;
}

export interface RegionOptions {
  /** The countries on offer, as ISO codes. Left out, every country. */
  countries?: readonly string[];
  /** Countries listed first, under Suggested: where most of your customers are. */
  suggestedCountries?: readonly string[];
  languages: readonly RegionChoice[];
  currencies: readonly RegionChoice[];
}

/** The fixed words, for a site that is not in English. */
export interface RegionLabels {
  /** The heading of the group, the title of the dialog on a phone, and the first words of the phone button for a screen reader. */
  region: string;
  /** The label of the country field, which also names its list for a screen reader. */
  country: string;
  language: string;
  currency: string;
  /** What the closed country field says while no country is chosen. */
  chooseCountry: string;
  /** The placeholder of the search field in the country list. */
  searchCountries: string;
  /** What the country list says when nothing matches the search. */
  noCountry: string;
  /** The heading over your suggested countries, at the top of the list. */
  suggested: string;
  /** The heading over all the other countries. */
  allCountries: string;
  /** Said under the title of the dialog on a phone. */
  description: string;
  /** The button that closes the dialog. */
  done: string;
  /** What a screen reader hears after a link that opens in a new tab. */
  newTab: string;
}

export const REGION_LABELS: RegionLabels = {
  region: "Region",
  country: "Country",
  language: "Language",
  currency: "Currency",
  chooseCountry: "Choose a country",
  searchCountries: "Search countries",
  noCountry: "No country found",
  suggested: "Suggested",
  allCountries: "All countries",
  description: "Choose the country you shop from, the language of the site and the currency of the prices.",
  done: "Done",
  newTab: "opens in a new tab",
};
